const canvas=document.getElementById('scene'),ctx=canvas.getContext('2d');
const gameEl=document.getElementById('game'),overlay=document.getElementById('overlay'),card=document.getElementById('card');
const heightEl=document.getElementById('height'),bestEl=document.getElementById('best'),starsEl=document.getElementById('stars'),toast=document.getElementById('toast');
let W=0,H=0,dpr=1,state='title',last=0,player,platforms=[],sparkles=[],birds=[],camera=0,score=0,best=Number(localStorage.getItem('jumpinBest')||0),stars=0,keys={left:false,right:false},toastTimer=0,worldTop=0;
bestEl.textContent=best+' m';
function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(dpr,0,0,dpr,0,0);if(state==='title')draw()}
addEventListener('resize',resize);resize();
function rand(a,b){return a+Math.random()*(b-a)}
function makePlatform(x,y,type='cloud',width=78){return{x,y,w:width,h:18,type,vx:type==='moving'?rand(45,90):0,phase:rand(0,7),alive:true}}
function reset(){score=0;stars=0;camera=0;worldTop=0;platforms=[];sparkles=[];player={x:W/2,y:95,vx:0,vy:0,r:17,face:1};platforms.push(makePlatform(W/2,58,'cloud',105));let y=175;while(y<H+240){let x=rand(48,W-48);platforms.push(makePlatform(x,y,'cloud',rand(66,88)));y+=rand(80,115)}addClouds();updateHUD()}
function addClouds(){birds=[];for(let i=0;i<8;i++)birds.push({x:rand(0,W),y:rand(-H,H*2),s:rand(.5,1.1),v:rand(8,19),phase:rand(0,6)})}
function start(){reset();state='play';overlay.classList.add('hidden');gameEl.classList.add('playing');last=performance.now();requestAnimationFrame(loop)}
function setOverlay(title,sub,button,label='PLAY AGAIN'){card.innerHTML=`<div class="hero-doodle">${title==='PAUSED'?'🌤️':'🪂'}</div><div class="eyebrow">☀️ &nbsp; A little sky-high adventure</div><h1>${title==='PAUSED'?'TAKE A':'NICE ONE,'}<span>${title==='PAUSED'?'BREATHER':'SKYHOPPER!'}</span></h1><p>${sub}</p>${title==='PAUSED'?'<button class="primary" id="resumeBtn">BACK TO IT &nbsp; ↗</button>':`<button class="primary" id="playAgain">${label} &nbsp; ↗</button>`}<div class="hint">Your best: <b>${best} m</b> &nbsp; · &nbsp; Every bounce is a new chance!</div>`;overlay.classList.remove('hidden');if(title==='PAUSED')document.getElementById('resumeBtn').onclick=resume;else document.getElementById('playAgain').onclick=start}
function pause(){if(state!=='play')return;state='pause';setOverlay('PAUSED','Catch your breath. Your cloud is right where you left it.','')}
function resume(){state='play';overlay.classList.add('hidden');last=performance.now();requestAnimationFrame(loop)}
function endGame(){if(state!=='play')return;state='over';gameEl.classList.remove('playing');if(score>best){best=score;localStorage.setItem('jumpinBest',best)}bestEl.textContent=best+' m';setOverlay('OVER','You floated up to <b>'+score+' m</b> and found <b>'+stars+' ⭐</b>. Ready for one more hop?','');draw()}
document.getElementById('playBtn').onclick=start;document.getElementById('pauseBtn').onclick=pause;
function loop(now){if(state!=='play')return;let dt=Math.min((now-last)/1000,.034);last=now;update(dt);draw();requestAnimationFrame(loop)}
function update(dt){let dir=(keys.right?1:0)-(keys.left?1:0);player.vx+=dir*1500*dt;player.vx*=Math.pow(.001,dt);player.vx=Math.max(-390,Math.min(390,player.vx));player.x+=player.vx*dt;if(player.vx)player.face=player.vx>0?1:-1;if(player.x<-player.r)player.x=W+player.r;if(player.x>W+player.r)player.x=-player.r;
 for(const p of platforms){if(p.type==='moving'){p.x+=p.vx*dt;if(p.x<p.w/2+8||p.x>W-p.w/2-8)p.vx*=-1}}
 let oldY=player.y;player.vy-=1500*dt;player.y+=player.vy*dt;
 if(player.vy<0){for(const p of platforms){if(!p.alive)continue;let feet=player.y-player.r;if(oldY-player.r>=p.y&&feet<=p.y&&player.x+player.r*.65>p.x-p.w/2&&player.x-player.r*.65<p.x+p.w/2){player.y=p.y+player.r;player.vy=p.type==='spring'?850:690;if(p.type==='fragile')p.alive=false;for(let i=0;i<7;i++)sparkles.push({x:player.x+rand(-18,18),y:p.y,vx:rand(-90,90),vy:rand(30,170),life:rand(.35,.65),c:'#fff0a5'});break}}}
 let follow=player.y-H*.61;if(follow>camera)camera+=(follow-camera)*Math.min(1,dt*4.2);camera=Math.max(0,camera);score=Math.max(score,Math.floor(Math.max(0,player.y-70)/10));worldTop=Math.max(worldTop,camera+H);while(Math.max(...platforms.map(p=>p.y))<camera+H+200){let lastP=platforms.reduce((a,b)=>a.y>b.y?a:b),gap=rand(78,116),y=lastP.y+gap,w=rand(62,85),x=rand(w/2+10,W-w/2-10);let type=Math.random()<Math.min(.26,.12+score/700)?'moving':'cloud';if(score>450&&Math.random()<.08)type='spring';platforms.push(makePlatform(x,y,type,w));if(Math.random()<.42)sparkles.push({x:rand(50,W-50),y:y+rand(32,55),coin:true,life:999})}
 platforms=platforms.filter(p=>p.y>camera-100);for(const s of sparkles){if(s.coin){if(Math.hypot(s.x-player.x,s.y-player.y)<player.r+13){s.coin=false;stars++;starsEl.textContent=stars;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),900)}}else{s.life-=dt;s.x+=s.vx*dt;s.y+=s.vy*dt;s.vy-=310*dt}}sparkles=sparkles.filter(s=>s.coin?s.y>camera-30:s.life>0);for(const b of birds){b.x+=b.v*dt;if(b.x>W+60)b.x=-60;b.phase+=dt*2}
 updateHUD();if(player.y<camera-80)endGame()}
function updateHUD(){heightEl.textContent=score+' m';bestEl.textContent=Math.max(best,score)+' m';starsEl.textContent=stars}
function rounded(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r)}
function drawCloud(x,y,s=1,alpha=1){ctx.save();ctx.globalAlpha=alpha;ctx.fillStyle='#fff';ctx.beginPath();ctx.ellipse(x,y,30*s,12*s,0,0,Math.PI*2);ctx.ellipse(x-14*s,y-5*s,14*s,13*s,0,0,Math.PI*2);ctx.ellipse(x+2*s,y-10*s,18*s,17*s,0,0,Math.PI*2);ctx.ellipse(x+18*s,y-4*s,13*s,12*s,0,0,Math.PI*2);ctx.fill();ctx.restore()}
function draw(){if(!W||!H)return;let g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#85d5f7');g.addColorStop(.55,'#c7edff');g.addColorStop(1,'#fff6df');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
 // soft distant cloud banks, anchored to the sky
 for(let i=0;i<9;i++){let x=((i*173+70)% (W+160))-80,y=((i*137+40-camera*.16)%(H+140)+H+140)%(H+140)-70;drawCloud(x,y,.75+(i%3)*.25,.25)}
 // tiny drifting birds
 for(const b of birds){let y=((b.y-camera*.32)%(H+100)+H+100)%(H+100)-45;ctx.save();ctx.translate(b.x,y);ctx.strokeStyle='rgba(78,146,176,.38)';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-7,1);ctx.quadraticCurveTo(-3,-5,0,1);ctx.quadraticCurveTo(4,-5,8,1);ctx.stroke();ctx.restore()}
 // floating star flecks
 for(let i=0;i<26;i++){let x=(i*97+23)%W,y=((i*151+camera*.48)%(H+30));ctx.globalAlpha=.22+.25*Math.sin(i+performance.now()/800);ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(x,y,1.5+(i%3)*.5,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
 for(const p of platforms){let sy=H-(p.y-camera);if(sy<-40||sy>H+40)continue;ctx.save();ctx.translate(p.x,sy);if(p.type==='cloud'){ctx.shadowColor='rgba(70,139,174,.18)';ctx.shadowBlur=8;ctx.shadowOffsetY=4;ctx.fillStyle='#fff';rounded(-p.w/2,-7,p.w,20,10);ctx.fill();ctx.shadowColor='transparent';ctx.fillStyle='#b9e8f4';rounded(-p.w/2+7,7,p.w-14,4,3);ctx.fill()}else if(p.type==='moving'){ctx.shadowColor='rgba(70,139,174,.2)';ctx.shadowBlur=8;ctx.shadowOffsetY=4;ctx.fillStyle='#fff';rounded(-p.w/2,-8,p.w,20,10);ctx.fill();ctx.shadowColor='transparent';ctx.fillStyle='#a8e8d1';rounded(-p.w/2+8,6,p.w-16,4,3);ctx.fill();ctx.fillStyle='#63bfa2';ctx.font='12px sans-serif';ctx.textAlign='center';ctx.fillText('✦',0,1)}else{ctx.fillStyle='#edaa63';rounded(-p.w/2,-9,p.w,21,8);ctx.fill();ctx.fillStyle='#ffd38e';rounded(-p.w/2+4,-5,p.w-8,6,3);ctx.fill()}ctx.restore()}
 for(const s of sparkles){let sy=H-(s.y-camera);if(s.coin){if(sy<-25||sy>H+25)continue;let pulse=1+Math.sin(performance.now()/180+s.x)*.09;ctx.save();ctx.translate(s.x,sy);ctx.scale(pulse,pulse);ctx.shadowColor='#ffc949';ctx.shadowBlur=13;ctx.fillStyle='#ffd454';ctx.beginPath();ctx.arc(0,0,11,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#fff7c7';ctx.font='bold 14px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('★',0,1);ctx.restore()}else{ctx.globalAlpha=Math.max(0,s.life*2);ctx.fillStyle=s.c;ctx.beginPath();ctx.arc(s.x,sy,3,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}}
 if(player){drawPlayer()}
 // horizon sun glow
 let sy=H-(camera+H*.78-camera);ctx.globalAlpha=.26;let sun=ctx.createRadialGradient(W*.82,sy,5,W*.82,sy,90);sun.addColorStop(0,'#fff');sun.addColorStop(1,'rgba(255,255,255,0)');ctx.fillStyle=sun;ctx.fillRect(W*.82-90,sy-90,180,180);ctx.globalAlpha=1}
function drawPlayer(){let sx=player.x,sy=H-(player.y-camera);if(sy<-100||sy>H+100)return;ctx.save();ctx.translate(sx,sy);ctx.scale(player.face,1);
 // backpack
 ctx.fillStyle='#ff927a';rounded(-18,-6,9,19,4);ctx.fill();
 // body and feet
 ctx.strokeStyle='#e87563';ctx.lineWidth=4;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-5,12);ctx.lineTo(-8,18);ctx.moveTo(6,12);ctx.lineTo(9,18);ctx.stroke();
 ctx.fillStyle='#4b91bf';rounded(-13,-3,26,20,10);ctx.fill();ctx.fillStyle='#77bbd6';rounded(-11,-1,22,10,7);ctx.fill();
 // head
 ctx.fillStyle='#ffd4aa';ctx.beginPath();ctx.arc(0,-12,12,0,Math.PI*2);ctx.fill();
 // hair tuft
 ctx.fillStyle='#805b50';ctx.beginPath();ctx.arc(-1,-18,9,Math.PI,Math.PI*2);ctx.quadraticCurveTo(9,-16,5,-12);ctx.quadraticCurveTo(1,-16,-4,-11);ctx.fill();
 ctx.fillStyle='#31495d';ctx.beginPath();ctx.arc(4,-12,1.4,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#de9279';ctx.lineWidth=1.3;ctx.beginPath();ctx.arc(4,-7,3,.2,1.7);ctx.stroke();
 // scarf flutter
 ctx.fillStyle='#ff826f';ctx.beginPath();ctx.moveTo(-5,0);ctx.quadraticCurveTo(-18,4,-21,0);ctx.quadraticCurveTo(-14,10,-7,5);ctx.fill();
 // soft shadow
 ctx.globalCompositeOperation='destination-over';ctx.fillStyle='rgba(45,103,133,.08)';ctx.beginPath();ctx.ellipse(0,22,17,4,0,0,Math.PI*2);ctx.fill();ctx.restore()}
function drawTitleScene(){reset();player.y=82;draw()}
// controls
addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight',' ','a','d','A','D'].includes(e.key))e.preventDefault();if(e.key==='ArrowLeft'||e.key.toLowerCase()==='a')keys.left=true;if(e.key==='ArrowRight'||e.key.toLowerCase()==='d')keys.right=true;if((e.key===' '||e.key==='Enter')&&state!=='play'&&state!=='pause')start();if(e.key==='Escape'||e.key==='p')state==='play'?pause():state==='pause'?resume():null});addEventListener('keyup',e=>{if(e.key==='ArrowLeft'||e.key.toLowerCase()==='a')keys.left=false;if(e.key==='ArrowRight'||e.key.toLowerCase()==='d')keys.right=false});
function bindTouch(id,key){let el=document.getElementById(id);el.addEventListener('pointerdown',e=>{e.preventDefault();keys[key]=true;el.setPointerCapture(e.pointerId)});for(let ev of ['pointerup','pointercancel','lostpointercapture'])el.addEventListener(ev,()=>keys[key]=false)}bindTouch('leftBtn','left');bindTouch('rightBtn','right');
// title scene
reset();player.y=82;draw();
</script>
</body>
</html>

const canvas=document.getElementById('scene'),ctx=canvas.getContext('2d'),gameEl=document.getElementById('game'),overlay=document.getElementById('overlay'),card=document.getElementById('card');const heightEl=document.getElementById('height'),bestEl=document.getElementById('best'),starsEl=document.getElementById('stars'),toast=document.getElementById('toast');let W=0,H=0,dpr=1,state='title',last=0,player,platforms=[],sparkles=[],birds=[],camera=0,score=0,best=Number(localStorage.getItem('jumpinBest')||0),stars=0,keys={left:false,right:false},toastTimer=0;bestEl.textContent=best+' m';
function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(dpr,0,0,dpr,0,0);draw()}addEventListener('resize',resize);function rand(a,b){return a+Math.random()*(b-a)}function makePlatform(x,y,type='cloud',width=78){return{x,y,w:width,h:18,type,vx:type==='moving'?rand(45,90):0,alive:true}}function reset(){score=0;stars=0;camera=0;platforms=[];sparkles=[];player={x:W/2,y:95,vx:0,vy:0,r:17,face:1};platforms.push(makePlatform(W/2,58,'cloud',105));let y=175;while(y<H+240){platforms.push(makePlatform(rand(48,W-48),y,'cloud',rand(66,88)));y+=rand(80,115)}birds=Array.from({length:8},()=>({x:rand(0,W),y:rand(-H,H*2),v:rand(8,19)}));updateHUD()}function start(){reset();state='play';overlay.classList.add('hidden');gameEl.classList.add('playing');last=performance.now();requestAnimationFrame(loop)}function setOverlay(title,sub){card.innerHTML=`<div class="hero-doodle">${title==='PAUSED'?'🌤️':'🪂'}</div><div class="eyebrow">☀️ &nbsp; A little sky-high adventure</div><h1>${title==='PAUSED'?'TAKE A':'NICE ONE,'}<span>${title==='PAUSED'?'BREATHER':'SKYHOPPER!'}</span></h1><p>${sub}</p>${title==='PAUSED'?'<button class="primary" id="resumeBtn">BACK TO IT &nbsp; ↗</button>':'<button class="primary" id="playAgain">PLAY AGAIN &nbsp; ↗</button>'}<div class="hint">Your best: <b>${best} m</b> &nbsp; · &nbsp; Every bounce is a new chance!</div>`;overlay.classList.remove('hidden');if(title==='PAUSED')document.getElementById('resumeBtn').onclick=resume;else document.getElementById('playAgain').onclick=start}function pause(){if(state!=='play')return;state='pause';setOverlay('PAUSED','Catch your breath. Your cloud is right where you left it.')}function resume(){state='play';overlay.classList.add('hidden');last=performance.now();requestAnimationFrame(loop)}function endGame(){if(state!=='play')return;state='over';gameEl.classList.remove('playing');if(score>best){best=score;localStorage.setItem('jumpinBest',best)}bestEl.textContent=best+' m';setOverlay('OVER','You floated up to <b>'+score+' m</b> and found <b>'+stars+' ⭐</b>. Ready for one more hop?');draw()}document.getElementById('playBtn').onclick=start;document.getElementById('pauseBtn').onclick=pause;function loop(now){if(state!=='play')return;let dt=Math.min((now-last)/1000,.034);last=now;update(dt);draw();requestAnimationFrame(loop)}
function update(dt){let dir=(keys.right?1:0)-(keys.left?1:0);player.vx+=dir*1500*dt;player.vx*=Math.pow(.001,dt);player.vx=Math.max(-390,Math.min(390,player.vx));player.x+=player.vx*dt;if(player.vx)player.face=player.vx>0?1:-1;if(player.x<-player.r)player.x=W+player.r;if(player.x>W+player.r)player.x=-player.r;for(const p of platforms)if(p.type==='moving'){p.x+=p.vx*dt;if(p.x<p.w/2+8||p.x>W-p.w/2-8)p.vx*=-1}let oldY=player.y;player.vy-=1500*dt;player.y+=player.vy*dt;if(player.vy<0)for(const p of platforms){if(!p.alive)continue;if(oldY-player.r>=p.y&&player.y-player.r<=p.y&&player.x+player.r*.65>p.x-p.w/2&&player.x-player.r*.65<p.x+p.w/2){player.y=p.y+player.r;player.vy=p.type==='spring'?850:690;if(p.type==='fragile')p.alive=false;for(let i=0;i<7;i++)sparkles.push({x:player.x+rand(-18,18),y:p.y,vx:rand(-90,90),vy:rand(30,170),life:rand(.35,.65),c:'#fff0a5'});break}}let follow=player.y-H*.61;if(follow>camera)camera+=(follow-camera)*Math.min(1,dt*4.2);camera=Math.max(0,camera);score=Math.max(score,Math.floor(Math.max(0,player.y-70)/10));while(Math.max(...platforms.map(p=>p.y))<camera+H+200){let lastP=platforms.reduce((a,b)=>a.y>b.y?a:b),y=lastP.y+rand(78,116),w=rand(62,85),x=rand(w/2+10,W-w/2-10),type=Math.random()<Math.min(.26,.12+score/700)?'moving':'cloud';if(score>450&&Math.random()<.08)type='spring';platforms.push(makePlatform(x,y,type,w));if(Math.random()<.42)sparkles.push({x:rand(50,W-50),y:y+rand(32,55),coin:true,life:999})}platforms=platforms.filter(p=>p.y>camera-100);for(const s of sparkles){if(s.coin){if(Math.hypot(s.x-player.x,s.y-player.y)<player.r+13){s.coin=false;stars++;starsEl.textContent=stars;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),900)}}else{s.life-=dt;s.x+=s.vx*dt;s.y+=s.vy*dt;s.vy-=310*dt}}sparkles=sparkles.filter(s=>s.coin?s.y>camera-30:s.life>0);for(const b of birds){b.x+=b.v*dt;if(b.x>W+60)b.x=-60}updateHUD();if(player.y<camera-80)endGame()}function updateHUD(){heightEl.textContent=score+' m';bestEl.textContent=Math.max(best,score)+' m';starsEl.textContent=stars}function rounded(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r)}function drawCloud(x,y,s=1,alpha=1){ctx.save();ctx.globalAlpha=alpha;ctx.fillStyle='#fff';ctx.beginPath();ctx.ellipse(x,y,30*s,12*s,0,0,Math.PI*2);ctx.ellipse(x-14*s,y-5*s,14*s,13*s,0,0,Math.PI*2);ctx.ellipse(x+2*s,y-10*s,18*s,17*s,0,0,Math.PI*2);ctx.ellipse(x+18*s,y-4*s,13*s,12*s,0,0,Math.PI*2);ctx.fill();ctx.restore()}

