+const sunX=W*.82,sunY=H*.21;const glow=ctx.createRadialGradient(sunX,sunY,5,sunX,sunY,100);glow.addColorStop(0,'rgba(255,244,187,.68)');glow.addColorStop(1,'rgba(255,244,187,0)');ctx.fillStyle=glow;ctx.fillRect(sunX-105,sunY-105,210,210);ctx.fillStyle='#fff4c4';ctx.beginPath();ctx.arc(sunX,sunY,27,0,Math.PI*2);ctx.fill();
+for(let i=0;i<7;i++){const y=((i*173-camera*.18)%(H+160)+H+160)%(H+160)-70;const x=(i*197+Math.sin(i*9)*30)%(W+130)-65;cloud(x,y,randConst(i,50,100),randConst(i,22,38),'rgba(255,255,255,.42)')}
+if(!player){cloud(W*.2,H*.76,140,62,'rgba(255,255,255,.76)');cloud(W*.78,H*.83,170,70,'rgba(255,255,255,.76)');drawGroundHint();return}
+for(const p of platforms){const sy=H-(p.y-camera);if(sy<-40||sy>H+30)continue;const x=p.x,y=sy;ctx.save();ctx.shadowColor='rgba(53,130,170,.15)';ctx.shadowBlur=10;ctx.shadowOffsetY=5;ctx.fillStyle=p.type==='safe'?'#ffcf83':p.type==='moving'?'#b8e6ab':'#fff';roundRect(x,y-p.h,p.w,p.h+5,8);ctx.fill();ctx.shadowColor='transparent';ctx.fillStyle=p.type==='safe'?'#ffe2a7':p.type==='moving'?'#d4f1c9':'#f0fbff';ctx.beginPath();ctx.ellipse(x+p.w*.25,y-p.h+2,12,7,0,Math.PI,0);ctx.ellipse(x+p.w*.55,y-p.h,15,9,0,Math.PI,0);ctx.ellipse(x+p.w*.8,y-p.h+3,11,6,0,Math.PI,0);ctx.fill();ctx.restore();if(p.star){const sx=x+p.w*.5,sy2=y-32+Math.sin(performance.now()/260+p.phase)*3;drawStar(sx,sy2,9,'#ffd65e')}}
+if(player){const sy=H-(player.y-camera);drawPlayer(player.x,sy,player.face)}
+for(let i=0;i<5;i++){const x=((i*239+camera*.09)%(W+20))-10,y=((i*127+camera*.31)%(H+20))-10;ctx.globalAlpha=.35+Math.sin(performance.now()/450+i)*.18;drawStar(x,y,3,'#fff8c9')}ctx.globalAlpha=1;
+}
+function randConst(seed,a,b){const n=Math.sin(seed*127.1+311.7)*43758.5453;return a+(n-Math.floor(n))*(b-a)}
+function roundRect(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r)}
+function drawStar(x,y,r,color){ctx.save();ctx.translate(x,y);ctx.rotate(performance.now()/900);ctx.fillStyle=color;ctx.strokeStyle='rgba(255,255,255,.8)';ctx.lineWidth=1.5;ctx.beginPath();for(let i=0;i<10;i++){const a=-Math.PI/2+i*Math.PI/5,rr=i%2?r*.46:r;ctx.lineTo(Math.cos(a)*rr,Math.sin(a)*rr)}ctx.closePath();ctx.fill();ctx.stroke();ctx.restore()}
+function drawPlayer(x,y,face){ctx.save();ctx.translate(x,y);ctx.scale(face,1);ctx.fillStyle='rgba(50,101,133,.13)';ctx.beginPath();ctx.ellipse(0,17,17,5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ff927e';ctx.beginPath();ctx.ellipse(0,3,14,15,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ffd2aa';ctx.beginPath();ctx.arc(0,-8,12,0,Math.PI*2);ctx.fill();ctx.fillStyle='#375a73';ctx.beginPath();ctx.arc(4,-9,1.5,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(-3,-9,1.5,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#c9705e';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(.5,-5,3,.2,Math.PI-.2);ctx.stroke();ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(-9,2,4,0,Math.PI*2);ctx.fill();ctx.restore()}
