+function inputDown(which,on){keys[which]=on}
+window.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight',' ','a','d','A','D'].includes(e.key))e.preventDefault();if(e.key==='ArrowLeft'||e.key.toLowerCase()==='a')inputDown('left',true);if(e.key==='ArrowRight'||e.key.toLowerCase()==='d')inputDown('right',true);if(e.key==='Escape'||e.key.toLowerCase()==='p'){if(state==='playing'||state==='paused')togglePause()}if((e.key==='Enter'||e.key===' ')&&(state==='menu'||state==='over'))newRun()});window.addEventListener('keyup',e=>{if(e.key==='ArrowLeft'||e.key.toLowerCase()==='a')inputDown('left',false);if(e.key==='ArrowRight'||e.key.toLowerCase()==='d')inputDown('right',false)});window.addEventListener('blur',()=>{keys.left=keys.right=false;if(state==='playing')togglePause()});
+for(const [id,dir] of [['leftBtn','left'],['rightBtn','right']]){const b=$(id);b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);inputDown(dir,true)});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>inputDown(dir,false))}
+playBtn.onclick=newRun;pauseBtn.onclick=togglePause;overlay.addEventListener('click',e=>{if(e.target===overlay&&state==='paused')resume()});resize();draw();
+})();
 </script></main></body></html>
