const fs=require('fs');
(async()=>{
 const tabs=await (await fetch('http://127.0.0.1:9222/json')).json();
 const tab=tabs.find(x=>x.type==='page');
 const ws=new WebSocket(tab.webSocketDebuggerUrl);
 await new Promise((ok,no)=>{ws.onopen=ok;ws.onerror=no});
 let id=0;const pending=new Map(),errors=[];
 ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.method==='Runtime.exceptionThrown')errors.push(m.params.exceptionDetails.text);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id)}};
 const send=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}))});
 await send('Runtime.enable');await send('Page.enable');
 await send('Runtime.evaluate',{expression:"document.getElementById('playBtn').click()"});
 await new Promise(r=>setTimeout(r,1400));
 const result=await send('Runtime.evaluate',{expression:"JSON.stringify({className:document.getElementById('game').className,height:document.getElementById('height').textContent,canvas:document.querySelector('canvas').width+'x'+document.querySelector('canvas').height})",returnByValue:true});
 const shot=await send('Page.captureScreenshot',{format:'jpeg',quality:82,fromSurface:true});
 fs.writeFileSync('/tmp/opencode/jumpin-gameplay.jpg',Buffer.from(shot.result.data,'base64'));
 console.log(result.result.result.value,JSON.stringify(errors),'jpeg bytes',Buffer.from(shot.result.data,'base64').length);
 ws.close();
})().catch(e=>{console.error(e);process.exit(1)});

